const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const vm = require("node:vm");
const { test } = require("node:test");
const {
  parseCommand,
  eligible,
  route,
  prepare,
  validateResult,
  parseReview,
  verify,
  report,
  dimensions,
} = require("./architecture-review-automation.cjs");

const repo = { owner: "example", repo: "broker" };
const head = "a".repeat(40);
const base = "b".repeat(40);
const issueURL = "https://api.github.com/repos/example/broker/issues/42";

function command(body, overrides = {}) {
  return { id: 20, body, issue_url: issueURL, user: { login: "maintainer", type: "User" }, ...overrides };
}

function commandEvent(entry, issue = { number: 42, pull_request: {} }) {
  return { action: "created", issue, comment: entry };
}

function finding(overrides = {}) {
  return {
    id: "F1", severity: "YELLOW", dimension: "ubiquitous-language", bucket: "proposed", title: "Overlap",
    change: "Rename ApprovalSession to reuse UserSession", alternative: "Keep both and document the difference", ...overrides,
  };
}

function state(overrides = {}) {
  return {
    run: "100/1", pr: 42, head, recommendation: "DISCUSS", summary: "One concern",
    findings: { RED: 0, YELLOW: 1, GREEN: 0 }, failed: [], items: [finding()], ...overrides,
  };
}

function review(data = state(), overrides = {}) {
  return {
    id: 30, issue_url: issueURL, user: { login: "github-actions[bot]", type: "Bot" },
    body: "## 🏗️ Architectural Review\n\nBody\n\n<details><summary>Review state</summary>\n\n## Architecture review result\n" +
      `\`\`\`json\n${JSON.stringify(data, null, 2)}\n\`\`\`\n\n</details>\n\n` +
      "> Generated by [Architecture Review](https://github.com/example/broker/actions/runs/100)\n\n" +
      "<!-- gh-aw-workflow-call-id: example/broker/architecture-review -->",
    ...overrides,
  };
}

function fixture(eventName, payload, options = {}) {
  const calls = [];
  const created = [];
  const deleted = [];
  const pr = {
    number: 42, state: "open", draft: true, merged_at: null, title: "Add approvals", body: "Adds approvals",
    html_url: "https://github.com/example/broker/pull/42",
    user: { login: "contributor", type: "User" },
    head: { ref: "feature/approvals", sha: head, repo: { full_name: "example/broker" } },
    base: { ref: "main", sha: base, repo: { full_name: "example/broker" } },
    ...options.pr,
  };
  const github = {
    rest: {
      repos: {
        getCollaboratorPermissionLevel: async (args) => {
          calls.push(args);
          return { data: { permission: options.permissions?.[args.username] || options.permission || "write" } };
        },
        getContent: async ({ ref, path: name }) => {
          assert.equal(name, "adrs");
          assert.equal(ref, base);
          if (options.noADRs) {
            const error = new Error("Not found");
            error.status = 404;
            throw error;
          }
          return { data: [
            { type: "file", name: "002-config.md", path: "adrs/002-config.md" },
            { type: "file", name: "README.md", path: "adrs/README.md" },
            { type: "dir", name: "drafts", path: "adrs/drafts" },
            { type: "file", name: "001-template.txt", path: "adrs/001-template.txt" },
          ] };
        },
      },
      pulls: {
        get: async () => ({ data: pr }),
        listFiles: async () => ({ data: options.files || [] }),
      },
      issues: {
        listComments: async () => ({ data: options.comments || [] }),
        getComment: async ({ comment_id }) => ({ data: (options.comments || []).find((entry) => entry.id === comment_id) }),
        createComment: async (args) => {
          created.push(args);
          return { data: { id: 900 + created.length, ...args } };
        },
        deleteComment: async ({ comment_id }) => {
          deleted.push(comment_id);
          return { data: {} };
        },
      },
    },
    paginate: async (method, args) => (await method(args)).data,
  };
  return { github, calls, created, deleted, context: { repo, eventName, payload, actor: "maintainer", runId: 100 } };
}

function withDirectory(t, files) {
  const sandbox = fs.mkdtempSync(path.join(os.tmpdir(), "architecture-review-"));
  const root = path.join(sandbox, "tmp/gh-aw/architecture-review");
  fs.mkdirSync(root, { recursive: true });
  for (const [name, content] of Object.entries(files)) fs.writeFileSync(path.join(root, name), content);
  t.after(() => fs.rmSync(sandbox, { recursive: true, force: true }));
  return root;
}

function runCommand(root, argument) {
  const source = fs.readFileSync(path.join(__dirname, "architecture-review-automation.cjs"), "utf8")
    .replaceAll('"/tmp/gh-aw/architecture-review"', JSON.stringify(root));
  const module = { exports: {} };
  const load = (name) => require(name);
  load.main = module;
  vm.runInNewContext(source, { module, require: load, process: { argv: ["node", "automation.cjs", argument] } });
}

function draft(overrides = {}) {
  const body = [
    "## 🏗️ Architectural Review", "", "### Executive Summary", "Fine.", "", "### Top Findings (Require Author Response)",
    `1. 🟡 **Overlap**: See https://github.com/example/broker/blob/${head}/internal/domain/approval/service.go.`, "",
    "### Concept Map", "| New | Location | Overlap | Question |", "|---|---|---|---|", "",
    "### Hexagonal Compliance", "✅ No violations", "", "### Pattern Consistency", "none", "",
    "### Coupling & Cohesion", "none", "", "### OTel Parity", "✅ OTel parity maintained", "",
    "### E2E Test Assessment", "| Flow | True E2E? | Assessment |", "|---|---|---|", "",
    "### Maintainability Forecast", "Low cost.", "", "### Recommendation", "**DISCUSS** — one overlap.", "",
  ].join("\n");
  return {
    recommendation: "DISCUSS", summary: "One naming overlap to discuss",
    findings: [finding()],
    dimensions: Object.fromEntries(dimensions.map((name) => [name, "assessed"])),
    body, ...overrides,
  };
}

const context = { run: "100/1", repository: "example/broker", pr: 42, head };

test("the command must start the comment and keeps its multi-line focus", () => {
  assert.deepEqual(parseCommand("/architecture-review"), { argument: "" });
  assert.deepEqual(parseCommand("/architecture-review focus on\nsessions"), { argument: "focus on\nsessions" });
  assert.equal(parseCommand("/architecture-reviewer"), null);
  assert.equal(parseCommand("Please /architecture-review"), null);
  assert.equal(parseCommand(null), null);
});

test("only open same-repository pull requests are eligible", () => {
  const pr = {
    state: "open", merged_at: null, head: { repo: { full_name: "example/broker" } }, base: { repo: { full_name: "example/broker" } },
  };
  assert.equal(eligible(pr, repo), true);
  assert.equal(eligible({ ...pr, state: "closed" }, repo), false);
  assert.equal(eligible({ ...pr, merged_at: "2026-10-28T10:00:00Z" }, repo), false);
  assert.equal(eligible({ ...pr, head: { repo: { full_name: "fork/broker" } } }, repo), false);
  assert.equal(eligible({ ...pr, head: { repo: null } }, repo), false);
});

test("a maintainer command on an open pull request routes to the review", async () => {
  const f = fixture("issue_comment", commandEvent(command("/architecture-review sessions")));
  assert.deepEqual(await route(f), { action: "review", pr: 42, comment: 20 });
  assert.deepEqual(f.calls, [{ ...repo, username: "maintainer" }]);
});

test("commands from read-only users, bots, other authors, edited comments, or plain text do not execute", async () => {
  const cases = [
    fixture("issue_comment", commandEvent(command("/architecture-review")), { permission: "read" }),
    fixture("issue_comment", commandEvent(command("/architecture-review", { user: { login: "github-actions[bot]", type: "Bot" } }))),
    fixture("issue_comment", commandEvent(command("/architecture-review", { user: { login: "contributor", type: "User" } }))),
    fixture("issue_comment", { ...commandEvent(command("/architecture-review")), action: "edited" }),
    fixture("issue_comment", commandEvent(command("Looks good, /architecture-review later"))),
    fixture("pull_request_review", { action: "submitted", review: command("/architecture-review") }),
  ];
  for (const f of cases) assert.deepEqual(await route(f), { action: "noop" });
});

test("commands on issues, closed, merged, or fork pull requests fail visibly for maintainers", async () => {
  await assert.rejects(route(fixture("issue_comment", commandEvent(command("/architecture-review"), { number: 7 }))),
    /runs on a pull request, not an issue/);
  for (const pr of [{ state: "closed" }, { merged_at: "2026-10-28T10:00:00Z" },
    { head: { ref: "x", sha: head, repo: { full_name: "fork/broker" } } }]) {
    await assert.rejects(route(fixture("issue_comment", commandEvent(command("/architecture-review")), { pr })),
      /open pull request from this repository/);
  }
});

test("Spec Kit's managed draft PRs are left to the Spec Kit pipeline", async () => {
  const pr = {
    draft: true, body: "<!-- speckit-issue: 7 -->", user: { login: "github-actions[bot]", type: "Bot" },
    head: { ref: "speckit/issue-7", sha: head, repo: { full_name: "example/broker" } },
  };
  const f = fixture("issue_comment", commandEvent(command("/architecture-review")), { pr });
  assert.deepEqual(await route(f), { action: "noop" });
  const ready = fixture("issue_comment", commandEvent(command("/architecture-review")), { pr: { ...pr, draft: false } });
  assert.deepEqual(await route(ready), { action: "review", pr: 42, comment: 20 });
});

test("a calling workflow may pass the review focus, but a command comment wins", async (t) => {
  t.mock.method(fs, "mkdirSync", () => undefined);
  const written = {};
  t.mock.method(fs, "writeFileSync", (name, content) => { written[path.basename(String(name))] = JSON.parse(content); });
  const f = fixture("issue_comment", {}, { comments: [command("/architecture-review sessions")] });
  assert.equal((await prepare({ ...f, inputs: { pr: "42", comment: "0", focus: "  Verify the remediation " } })).focus,
    "Verify the remediation");
  assert.equal((await prepare({ ...f, inputs: { pr: "42", comment: "20", focus: "ignored" } })).focus, "sessions");
  await assert.rejects(prepare({ ...f, inputs: { pr: "42", comment: "0", focus: "x".repeat(2001) } }), /Invalid review focus/);
  assert.equal(written["context.json"].focus, "sessions");
});

test("prepare writes the compact context and PR details with changed files and ADR provenance", async (t) => {
  const root = withDirectory(t, {});
  t.mock.method(fs, "mkdirSync", () => undefined);
  const written = {};
  t.mock.method(fs, "writeFileSync", (name, content) => { written[path.basename(String(name))] = JSON.parse(content); });
  const files = [
    { filename: "internal/domain/approval/service.go", status: "modified", additions: 10, deletions: 2 },
    { filename: "adrs/045-approvals.md", status: "added", additions: 40, deletions: 0 },
    { filename: "adrs/002-config.md", status: "modified", additions: 1, deletions: 1 },
    { filename: "adrs/drafts/x.md", status: "added", additions: 1, deletions: 0 },
    { filename: "internal/domain/approval/model.go", status: "renamed", additions: 0, deletions: 0, previous_filename: "internal/domain/approval/types.go" },
  ];
  const f = fixture("issue_comment", {}, {
    files, comments: [command("/architecture-review sessions")],
    pr: { body: "Summary\n\n<!-- speckit-feature: specs/054-approvals -->" },
  });
  process.env.GITHUB_RUN_ATTEMPT = "2";
  const data = await prepare({ ...f, inputs: { pr: "42", comment: "20" } });
  assert.equal(root.length > 0, true);
  assert.deepEqual(data, {
    run: "100/2", repository: "example/broker", pr: 42, head, branch: "feature/approvals", base: "main", base_sha: base,
    feature: "specs/054-approvals", focus: "sessions", command: { id: 20, author: "maintainer", argument: "sessions" },
  });
  assert.deepEqual(written["context.json"], data);
  const details = written["pr-details.json"];
  assert.equal(details.headRefOid, head);
  assert.equal(details.baseRefOid, base);
  assert.equal(details.feature, "specs/054-approvals");
  assert.deepEqual(details.changedFiles[4], {
    path: "internal/domain/approval/model.go", status: "renamed", additions: 0, deletions: 0,
    previous_path: "internal/domain/approval/types.go",
  });
  assert.deepEqual(details.adrs, {
    existing: ["adrs/002-config.md", "adrs/README.md"], added: ["adrs/045-approvals.md"], modified: ["adrs/002-config.md"],
  });
  assert.deepEqual(f.calls.map((call) => call.username), ["maintainer", "maintainer"]);
});

test("prepare fails closed for non-maintainers, ineligible PRs, and forged command comments", async (t) => {
  t.mock.method(fs, "mkdirSync", () => undefined);
  t.mock.method(fs, "writeFileSync", () => undefined);
  await assert.rejects(prepare({ ...fixture("issue_comment", {}, { permission: "read" }), inputs: { pr: "42" } }),
    /Maintainer permission is required/);
  await assert.rejects(prepare({ ...fixture("issue_comment", {}, { pr: { state: "closed" } }), inputs: { pr: "42" } }),
    /Only open, same-repository pull requests/);
  await assert.rejects(prepare({ ...fixture("issue_comment", {}), inputs: { pr: "0" } }), /pull request number is required/);
  const forged = [
    command("/architecture-review", { user: { login: "contributor", type: "User" } }),
    command("/architecture-review", { issue_url: "https://api.github.com/repos/example/broker/issues/43" }),
    command("Not a command"),
    command("/architecture-review", { user: { login: "github-actions[bot]", type: "Bot" } }),
  ];
  for (const entry of forged) {
    const f = fixture("issue_comment", {}, { comments: [entry], permissions: { maintainer: "write", contributor: "read" } });
    await assert.rejects(prepare({ ...f, inputs: { pr: "42", comment: "20" } }), /not an eligible maintainer command/);
  }
  const f = fixture("issue_comment", {}, { noADRs: true });
  const data = await prepare({ ...f, inputs: { pr: "42", comment: "0" } });
  assert.equal(data.command, undefined);
  assert.equal(data.focus, "");
});

test("results need every dimension, consistent severities, remediation buckets, and head-pinned links", () => {
  assert.deepEqual(validateResult(draft(), context), {
    run: "100/1", pr: 42, head, recommendation: "DISCUSS", summary: "One naming overlap to discuss",
    findings: { RED: 0, YELLOW: 1, GREEN: 0 }, failed: [], items: [finding()],
  });
  const reject = (overrides, pattern) => assert.throws(() => validateResult(draft(overrides), context), pattern);
  reject({ recommendation: "LGTM" }, /Invalid recommendation/);
  reject({ summary: "a\nb" }, /one-line summary/);
  reject({ findings: Array(8).fill(finding()) }, /at most 7/);
  reject({ findings: [finding({ id: "x" })] }, /Invalid review item id/);
  reject({ findings: [finding(), finding()] }, /Invalid review item id/);
  reject({ findings: [finding({ severity: "ORANGE" })] }, /Invalid review item F1/);
  reject({ findings: [finding({ dimension: "unknown" })] }, /Invalid review item F1/);
  reject({ findings: [finding({ bucket: "maybe" })] }, /Invalid review item F1/);
  reject({ findings: [finding({ bucket: "note" })] }, /needs a remediation bucket/);
  reject({ findings: [finding({ bucket: "auto", change: undefined })] }, /needs a one-line recommended change/);
  reject({ findings: [finding({ bucket: "question", question: undefined })] }, /needs a one-line question/);
  reject({ findings: [finding({ alternative: "a\nb" })] }, /invalid alternative/);
  reject({ findings: [finding({ title: "x".repeat(201) })] }, /Invalid review item F1/);
  reject({ findings: ["F1"] }, /Invalid finding/);
  reject({ dimensions: { "otel-parity": "assessed" } }, /Every analysis dimension/);
  reject({ dimensions: { ...draft().dimensions, "otel-parity": "skipped" } }, /Every analysis dimension/);
  reject({ findings: [finding({ severity: "RED", dimension: "adr-compliance", title: "Second mechanism" })] }, /requires REQUEST CHANGES/);
  reject({ findings: [], recommendation: "REQUEST CHANGES", body: draft().body.replace("**DISCUSS**", "**REQUEST CHANGES**") },
    /needs at least one/);
  reject({ findings: [], recommendation: "APPROVE", dimensions: { ...draft().dimensions, "otel-parity": "failed" },
    body: draft().body.replace("**DISCUSS**", "**APPROVE**") }, /cannot approve/);
  reject({ body: "Hello" }, /must start with the review heading/);
  reject({ body: draft().body.replace("\n### OTel Parity", "\n### Telemetry") }, /missing the "### OTel Parity"/);
  reject({ body: draft().body.replace("**DISCUSS**", "DISCUSS") }, /must state the recommendation/);
  reject({ body: `${draft().body}\n<!-- architecture-review: {} -->` }, /reserved markers/);
  reject({ body: `${draft().body}\n<!-- gh-aw-workflow-call-id: x -->` }, /reserved markers/);
  reject({ body: `${draft().body}\n## Architecture review result\n` }, /reserved markers/);
  reject({ dimensions: { ...draft().dimensions, "otel-parity": "failed", maintainability: "failed" },
    body: draft().body.replace("✅ OTel parity maintained", "⚠️ Dimension not assessed") }, /More than one unassessed dimension/);
  reject({ body: draft().body.replace(head, "main") }, /File links must use/);
  reject({ body: draft().body.replace("example/broker", "other/repo") }, /File links must use/);
  reject({ body: `${draft().body}${"x".repeat(60000)}` }, /exceeds 60000/);
  reject({ dimensions: { ...draft().dimensions, "otel-parity": "failed" } }, /not assessed/);
  const partial = validateResult(draft({
    dimensions: { ...draft().dimensions, "otel-parity": "failed" },
    body: draft().body.replace("✅ OTel parity maintained", "⚠️ Dimension not assessed: the sub-agent failed twice."),
  }), context);
  assert.deepEqual(partial.failed, ["otel-parity"]);
});

test("the result command appends the machine-readable state to the published comment", (t) => {
  const root = withDirectory(t, { "context.json": JSON.stringify(context), "result.json": JSON.stringify(draft()) });
  runCommand(root, "result");
  const comment = fs.readFileSync(path.join(root, "comment.md"), "utf8");
  assert.ok(comment.startsWith("## 🏗️ Architectural Review\n"));
  assert.ok(comment.endsWith("\n\n<details><summary>Review state</summary>\n\n## Architecture review result\n```json\n" + JSON.stringify({
    run: "100/1", pr: 42, head, recommendation: "DISCUSS", summary: "One naming overlap to discuss",
    findings: { RED: 0, YELLOW: 1, GREEN: 0 }, failed: [], items: [finding()],
  }, null, 2) + "\n```\n\n</details>\n"));
  assert.ok(!comment.includes("<!--"));
  fs.writeFileSync(path.join(root, "result.json"), JSON.stringify(draft({ recommendation: "APPROVE" })));
  assert.throws(() => runCommand(root, "result"), /must state the recommendation/);
  assert.throws(() => runCommand(root, "unknown"), /Expected the result command/);
});

test("review parsing requires the trusted workflow footer, one valid marker, and a matching PR", () => {
  assert.deepEqual(parseReview(review()), state());
  assert.equal(parseReview(review(state(), { user: { login: "maintainer", type: "User" } })), null);
  assert.equal(parseReview(review(state(), { issue_url: "https://api.github.com/repos/example/broker/issues/43" })), null);
  assert.equal(parseReview(review(state({ head: "short" }))), null);
  assert.equal(parseReview(review(state({ recommendation: "LGTM" }))), null);
  assert.equal(parseReview(review(state({ failed: ["nope"] }))), null);
  assert.equal(parseReview(review(state({ items: [] }))), null);
  assert.equal(parseReview(review(state({ items: [finding({ bucket: "note" })] }))), null);
  const entry = review();
  assert.equal(parseReview({ ...entry, body: entry.body.replace("example/broker/architecture-review", "other/broker/architecture-review") }), null);
  assert.equal(parseReview({ ...entry, body: entry.body.replace("/architecture-review -->", "/speckit-analyze -->") }), null);
  assert.equal(parseReview({ ...entry, body: `${entry.body}\n<!-- gh-aw-workflow-call-id: example/broker/architecture-review -->` }), null);
  assert.equal(parseReview({ ...entry, body: entry.body.replace("## Architecture review result", "## Architecture review result\n## Architecture review result") }), null);
  assert.equal(parseReview({ ...entry, body: entry.body.replace("</details>", "```json\n{}\n```\n</details>") }), null);
  assert.equal(parseReview({ ...entry, body: entry.body.replace(/```json\n[\s\S]*?\n```\n/, "") }), null);
  assert.equal(parseReview({ ...entry, body: entry.body.replace("## Architecture review result", "## Other") }), null);
});

test("verification accepts the current run's review on an unchanged PR and rejects stale or foreign ones", async () => {
  const f = fixture("issue_comment", {}, { comments: [review()] });
  assert.deepEqual(await verify({ ...f, comment: "30" }), state());
  await assert.rejects(verify({ ...f, comment: "" }), /did not publish/);
  await assert.rejects(verify({ ...fixture("issue_comment", {}, { comments: [review(state({ run: "99/1" }))] }), comment: "30" }),
    /provenance/);
  await assert.rejects(verify({ ...fixture("issue_comment", {}, { comments: [command("/architecture-review", { id: 30 })] }), comment: "30" }),
    /provenance/);
  await assert.rejects(verify({ ...fixture("issue_comment", {}, { comments: [review()], pr: { head: { ref: "x", sha: "c".repeat(40), repo: { full_name: "example/broker" } } } }), comment: "30" }),
    /changed while it was reviewed/);
  await assert.rejects(verify({ ...fixture("issue_comment", {}, { comments: [review()], pr: { state: "closed" } }), comment: "30" }),
    /not on an open/);
});

test("a failed run replaces the status comment with the reason; a successful run only removes it", async () => {
  const stale = { id: 60, body: `## 🏗️ Architecture review · ⛔\n\n${"<!-- architecture-review-status -->"}\n`,
    user: { login: "github-actions[bot]", type: "Bot" } };
  const f = fixture("issue_comment", commandEvent(command("/architecture-review")), { comments: [stale] });
  const data = await report({ ...f, needs: {
    route: { result: "failure", outputs: { error: "/architecture-review runs on an open pull request <b> @team" } },
  } });
  assert.deepEqual(f.deleted, [60]);
  assert.equal(data.body, [
    "## 🏗️ Architecture review · ⛔ Stopped in `route`", "",
    "/architecture-review runs on an open pull request &lt;b> @​team", "",
    "[Workflow run](https://github.com/example/broker/actions/runs/100)", "", "<!-- architecture-review-status -->", "",
  ].join("\n"));

  const failed = fixture("issue_comment", commandEvent(command("/architecture-review")));
  const posted = await report({ ...failed, needs: {
    route: { result: "success", outputs: { action: "review", pr: "42" } }, review: { result: "failure", outputs: {} },
    verify: { result: "skipped", outputs: {} },
  } });
  assert.ok(posted.body.startsWith("## 🏗️ Architecture review · ⛔ `review` failed\n\nThe job failed before publishing a review."));

  const success = fixture("issue_comment", commandEvent(command("/architecture-review")), { comments: [stale] });
  assert.equal(await report({ ...success, needs: {
    route: { result: "success", outputs: { action: "review", pr: "42" } }, review: { result: "success", outputs: { comment_id: "30" } },
    verify: { result: "success", outputs: {} },
  } }), null);
  assert.deepEqual(success.deleted, [60]);
  assert.equal(success.created.length, 0);

  const noop = fixture("issue_comment", commandEvent(command("hello")));
  assert.equal(await report({ ...noop, needs: { route: { result: "success", outputs: { action: "noop" } } } }), null);
  const outsider = fixture("issue_comment", commandEvent(command("/architecture-review")), { permission: "read" });
  assert.equal(await report({ ...outsider, needs: { route: { result: "failure", outputs: { error: "x" } } } }), null);
  assert.equal(outsider.created.length, 0);
});
